// Money is whole cents.
//
// Percentage amounts are rounded to the nearest whole cent, with exact halves
// rounding up. Work in integers so no floating point drift can move a half.
export function percentOf(cents, percent) {
  const exact = cents * percent; // in "hundredths of a cent", an exact integer
  return divideRoundHalfUp(exact, 100);
}

// Divide two integers, rounding the quotient to the nearest whole unit with
// exact halves rounded up (towards +Infinity).
function divideRoundHalfUp(numerator, denominator) {
  return Math.floor((numerator + denominator / 2) / denominator);
}

export function sum(values) {
  return values.reduce((total, value) => total + value, 0);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { invoiceTotal } from '../src/invoice.js';
import { percentOf } from '../src/money.js';

test('a round order totals exactly', () => {
  assert.equal(invoiceTotal({ items: [{ priceCents: 1000, quantity: 2 }], discountPercent: 10, taxPercent: 10 }), 1980);
});

// 15% of 1999 is 299.85 cents, which rounds up to 300 (not down to 299).
// Net is therefore 1699, and 8% of 1699 is 135.92, rounding to 136.
test('reported order rounds discount and tax half up to 1835', () => {
  assert.equal(
    invoiceTotal({ items: [{ priceCents: 1999, quantity: 1 }], discountPercent: 15, taxPercent: 8 }),
    1835,
  );
});

test('a discount-only order rounds its percentage amount up', () => {
  assert.equal(invoiceTotal({ items: [{ priceCents: 1999, quantity: 1 }], discountPercent: 15, taxPercent: 0 }), 1699);
});

test('a tax-only order rounds its percentage amount up', () => {
  assert.equal(invoiceTotal({ items: [{ priceCents: 1999, quantity: 1 }], taxPercent: 8 }), 2159);
});

test('percentOf rounds an exact half up and just below it down', () => {
  assert.equal(percentOf(1005, 10), 101); // 100.5 -> 101
  assert.equal(percentOf(1004, 10), 100); // 100.4 -> 100
  assert.equal(percentOf(1009, 10), 101); // 100.9 -> 101
});

test('percentOf handles zero percent and zero amounts', () => {
  assert.equal(percentOf(1999, 0), 0);
  assert.equal(percentOf(0, 15), 0);
});

import { invoiceTotal } from '../src/invoice.js';
import { percentOf } from '../src/money.js';

const total = invoiceTotal({ items: [{ priceCents: 1999, quantity: 1 }], discountPercent: 15, taxPercent: 8 });
console.log('reported order total:', total);

const cases = [
  [1999, 15, 300],
  [1999, 8, 160],
  [1005, 10, 101],
  [1004, 10, 100],
  [1999, 0, 0],
];
let ok = total === 1835;
for (const [cents, percent, expected] of cases) {
  const actual = percentOf(cents, percent);
  if (actual !== expected) {
    ok = false;
    console.log('percentOf mismatch', { cents, percent, actual, expected });
  }
}
console.log(ok ? 'rounding checks passed' : 'rounding checks FAILED');
process.exit(ok ? 0 : 1);

